body:
Please consider following code: void process(int N, int K, const vector<int>& data)
{
    #pragma omp parallel for
    for(int i = 0; i < data.size(); ++i)
    {
        //perform some processing based on data, N and K
    }
}

void solve(int N, int K, const vector<int>& data)
{
    for(int i = 0; i < N; ++i)
    {
        for(int j = 0; j < K; ++j)
        {
            process(N, K, data);
        }
    }
} Code above is executed with different size of each parameters.
N and K are in range 1 - 1000 (in most cases). Very often both are 1.
data.size() also varies a lot and is between 100 and 300 000. The code above in most cases works great. The problem is if N or K are greater than ~100. e.g. K is 300 and data is not so large. e.g.: 1000. 
In such cases most of the time my program is waiting for waking up the omp threads. And if I disable omp then in such case the program is 2-3 times faster. My question is - is it possible to somehow instrument omp to keep spinlocks when executing loops inside solve function ?
I have tried OMP_WAIT_POLICY Active and it solves the problem, but because of other reasons (it is small part of big application) I have to stay with Passive mode so far. Is there an other option to keep the threads Active for a while (or any other idea how to fix this issue)? Edit:
According to @Gilles here is my full test program: #include <atomic>
#include <iostream>
#include <vector>
#include <chrono>
#include <omp.h>

std::atomic<int> cnt;

void process(int a, int b, std::vector<int>& d)
{
    #pragma omp parallel for 
    for (int i = 0; i < d.size(); ++i)
    {
        //sample operation
        if (d[i] > a + b)
            ++cnt;
    }
}

void solve(int N, int K, std::vector<int>& d)
{
    for (int i = 0; i < N; ++i)
    {
        for (int j = 0; j < K; ++j)
        {
            process(i, j, d);
        }
    }
}

void RunTest(int numOfThreads, int N, int K, int arrSize)
{
    std::vector<int> s(arrSize);
    s[0] = s[10] = 1000;

    omp_set_num_threads(numOfThreads);
    cnt = 0;

    std::chrono::duration<double> minDiff = std::chrono::duration<double>{ 99999999 };
    for (int iters = 0; iters < 20; ++iters)
    {
        auto start = std::chrono::high_resolution_clock::now();
        solve(N, K, s);
        auto end = std::chrono::high_resolution_clock::now();

        std::chrono::duration<double> diff = end - start;
        if (diff < minDiff)
            minDiff = diff;
    }
    std::cout << "Time: " << minDiff.count() * 1000 << " ms \t\t" << "Threads: " << numOfThreads << " N: " << N << " K: " << K << std::endl;
}

int main()
{
    std::cout << "Large N*K" << std::endl;
