    all_rotations[i] = rotated;
}

if ( verbose ) { printVec(&all_rotations, "Rotations"); }

return all_rotations;
} I pre-calculated the number of possible rotations and used the #pragma omp parallel for, so it should do what I think it does. To test these functions, I have a 40KB large text-file which is meant to be "rotated". I wanna have all the distinct rotations of a giant text. What happens now is, that the sequential procedure tooks like 4.3 seconds and the parallel tooks like 6.5 seconds. Why is that so? What am I doing wrong? This is how I measure time: clock_t start, finish;
start = clock();
bwt_encode_parallel( &glob_word, &seperator );
finish = clock();
