answers.body:
There are two race conditions in your code that are leading to incorrect results: One was already pointed out in the comments, i.e., the updates of the variable sum ( shared among threads ), which can be solved with the reduction clause; The other is the updates of the variable x , which is also shared among the threads . This race condition can be solved by simply making that variable private to threads. Two possible solutions: Using the OpenMP's private constructor #pragma omp parallel for reduction(+:sum) private(x)
 for (i = 0; i < num_steps; i++)
 {
      x = (i + 0.5) * step;
      sum = sum + 4.0 / (1.0 + x * x);
 } Declaring the variable 'x' within the scope of the parallel for #pragma omp parallel for reduction(+:sum)
 for (i = 0; i < num_steps; i++)
 {
      double x = (i + 0.5) * step;
      sum = sum + 4.0 / (1.0 + x * x);
 } The final code could look like the following: #include <omp.h>
    #include <stdio.h>

    static long num_steps = 1000000;
    #define NUM_THREADS 16

    int main()
    {
        double sum = 0.0;
        omp_set_num_threads(NUM_THREADS);
        double step = 1.0 / (double)num_steps;

        double tdata = omp_get_wtime();

        #pragma omp parallel for reduction(+:sum)
        for (int i = 0; i < num_steps; i++)
        {
             double x = (i + 0.5) * step;
             sum = sum + 4.0 / (1.0 + x * x);
        }

        tdata = omp_get_wtime() - tdata;
        double pi = sum * step;
        printf("pi = %f and compute time = %f seconds", pi, tdata);
    }

