Here is the code updated Sep 2022. By adding and removing -03 gcc optimizations are switched on and off. Yes, Godbolt will refuse to run from time to time, since that is a large data set for Godbolt. For better benchmarking run locally. Here is the code refactored . And perhaps meaningful. Using sheredom/ubench .
Please spot the compiler arguments: -fopenmp -s -lm -O3 . Play with -O and spot the difference. (As a side note, please read: 32 OpenMP Traps for C++ Developers ) Here is the code: #include "https://raw.githubusercontent.com/sheredom/ubench.h/master/ubench.h"

#include <assert.h>
#include <omp.h>
#include <stdio.h>
#include <stdlib.h>

    #define DATA_SIZE 100000
    #define N_THREADS 2
    #define range DATA_SIZE/N_THREADS

static struct {
    float x_f[DATA_SIZE] ;
    float y_f[DATA_SIZE] ;
    double x_d[DATA_SIZE] ;
    double y_d[DATA_SIZE] ;
} * app_data = 0 ;

static void app_start (void) 
{
    app_data = calloc(1, sizeof(*app_data) );
    assert(app_data) ;

  for (int i = 0; i < DATA_SIZE; ++i) {
    app_data->x_f[i] = 1.0f;
    app_data->y_f[i] = 2.0f;
    app_data->x_d[i] = 1.0;
    app_data->y_d[i] = 2.0;
  }
}

UBENCH( omp_measuring, adding_two_arrays_of_floats )
{
    #pragma omp parallel num_threads(N_THREADS)
  {
      const int thread_id = omp_get_thread_num();

      const int begin = range * thread_id;
      int end = begin + range;
      if (thread_id + 1 == N_THREADS)
          end = DATA_SIZE;

      for (int i = begin; i < end; i++) {
          app_data->x_f[i] += app_data->y_f[i];
      }
  }
}

UBENCH( omp_measuring, adding_two_arrays_of_doubles )
{
    #pragma omp parallel num_threads(N_THREADS)
  {
      const int thread_id = omp_get_thread_num();

      const int begin = range * thread_id;
      int end = begin + range;
      if (thread_id + 1 == N_THREADS)
          end = DATA_SIZE;

      for (int i = begin; i < end; i++) {
          app_data->x_d[i] += app_data->y_d[i];
      }
  }
}

static void app_end (void) { free(app_data); }


UBENCH_STATE();

int main(int argc, const char *const argv[])
{
    app_start();

    ubench_main(argc, argv);

    app_end();

} Caveat Emptor The whole point of OMP is (very) moot since OMP apparently works only if optimizations are not used. It is very hard to beat gnuc -O3 . The problem with Godbolt is it chokes on large data sets. On VLA's (aka Very Large Arrays) using OMP should appear as meaningful. In reality, it is very rare to have to deal with megabyte or gigabyte datasets. And then one might imagine GPU's being used. No OMP. Bonus app_start is not prescribed by UBENCH. One can pass application command line arguments to a different app_start : static void app_start(const unsigned argc, char ** argv )
{
   // use app arguments here
}

int main (int argc, char ** argv) 
{
      app_start(argc,argv);
      ubench_main(argc,argv);
      app_end();
}

