        for (j = 0; j < N; j+=BS) {
            for (k = 0; k < N; k+=BS) {
                // Note 1: i, j, k, A, B, C are firstprivate by default
                // Note 2: A, B and C are just pointers
                #pragma omp task private(ii, jj, kk) \
                    depend ( in: A[i:BS][k:BS], B[k:BS][j:BS] ) \
                        depend ( inout: C[i:BS][j:BS] )
                for (ii = i; ii < i+BS; ii++ )
                    for (jj = j; jj < j+BS; jj++ ) {
                        for (kk = k; kk < k+BS; kk++ )
                            C[ii][jj] = C[ii][jj] + A[ii][kk] * B[kk][jj];
                    }                
            }
        }
    }
}

void matmul_iter(int N, int BS, float **A, float **B, float **C) {
    int i, j, k, ii, jj, kk;
    for (i = 0; i < N; i+=BS) {
        for (j = 0; j < N; j+=BS) {
            for (k = 0; k < N; k+=BS) {
                #pragma omp task private(ii, jj, kk) \
                    depend (iterator (i1 = i:i+BS-1, j1 = j:j+BS-1, k1 = k:k+BS-1),  in: A[i1][k1], B[k1][j1] ) \
                        depend (iterator (i1 = i:i+BS-1, j1 = j:j+BS-1), inout: C[i1][j1] )
                for (ii = i; ii < i+BS; ii++ )
                    for (jj = j; jj < j+BS; jj++ )
                        for (kk = k; kk < k+BS; kk++ ) {
                            assert(ii < N && kk < N && jj < N);
                            C[ii][jj] = C[ii][jj] + A[ii][kk] * B[kk][jj];
                        }
            }
        }
    }
}


